/* Rewards investing concept. Every fund, rate, order and unit is fictional. */
'use strict';
const rewardFunds=[
  {id:'index',name:'India Equity Index',type:'Equity · Demo fund',risk:'Higher risk',description:'An illustrative broad-market equity investment.',navPaise:12540},
  {id:'balanced',name:'Balanced Allocation',type:'Hybrid · Demo fund',risk:'Moderately high risk',description:'An illustrative mix of equity and debt investments.',navPaise:15000},
  {id:'debt',name:'Short Duration Debt',type:'Debt · Demo fund',risk:'Moderate risk',description:'An illustrative short-duration debt investment.',navPaise:2500}
];
const REWARD_RATE_PAISE=10;
const REWARD_MIN_POINTS=100;
const REWARD_NAV_DATE='2026-10-26';
let rewardFilter='All',rewardChartRange='6M',rewardChartMonth=null;
function initialRewards(){return{version:1,availablePoints:8400,pendingPoints:1260,ready:false,fundId:null,consent:false,redemptions:[],orders:[
  {id:'ELV-RW-0002',points:21000,amountPaise:210000,fundId:'index',status:'allotted',units:16.8,navPaise:12500,date:'12 Oct 2026',source:'Previous demo conversion'},
  {id:'ELV-RW-0001',points:15000,amountPaise:150000,fundId:'index',status:'allotted',units:12,navPaise:12500,date:'12 Sep 2026',source:'Previous demo conversion'}
]}}
function ensureRewardsState(member){if(!member.rewards||member.rewards.version!==1)member.rewards=initialRewards();if(!Array.isArray(member.rewards.redemptions))member.rewards.redemptions=[];return member}
function rewardSummary(){
  const r=state.rewards;
  return{availablePoints:r.availablePoints,pendingPoints:r.pendingPoints,availablePaise:r.availablePoints*REWARD_RATE_PAISE,
    investedPaise:r.orders.filter(o=>o.status==='allotted').reduce((s,o)=>s+o.amountPaise,0),
    processingPaise:r.orders.filter(o=>o.status!=='allotted').reduce((s,o)=>s+o.amountPaise,0),
    convertedPoints:r.orders.reduce((s,o)=>s+o.points,0),
    lastPending:r.orders.find(o=>o.status!=='allotted')};
}
// Portfolio valuation uses allotted units only. Pending conversions are not holdings.
function rewardInvestmentDate(order){const date=order.allottedOn||order.date?.split(' · ')[0];return date?Date.parse(date+( /^\d{4}-\d{2}-\d{2}$/.test(date)?'T00:00:00Z':' 00:00:00 GMT')):NaN}
function rewardPortfolio(){
  const orders=state.rewards.orders.filter(o=>o.status==='allotted'),asOf=Date.parse(REWARD_NAV_DATE+'T00:00:00Z');
  const investedPaise=orders.reduce((sum,o)=>sum+o.amountPaise,0);
  const valued=orders.map(o=>({order:o,fund:rewardFunds.find(f=>f.id===o.fundId)}));
  const complete=valued.every(({order:o,fund:f})=>f&&Number.isFinite(o.units)&&o.units>=0);
  const currentPaise=complete?Math.round(valued.reduce((sum,{order:o,fund:f})=>sum+o.units*f.navPaise,0)):null;
  const cashflows=orders.map(o=>({amountPaise:o.amountPaise,date:rewardInvestmentDate(o)}));
  return{investedPaise,currentPaise,gainPaise:currentPaise===null?null:currentPaise-investedPaise,xirr:rewardXirr(cashflows,currentPaise,asOf)};
}
// With contribution-only outflows and one terminal value, NPV is monotonic in log(1+r).
function rewardXirr(contributions,currentPaise,asOf){
  if(!contributions.length||!Number.isFinite(currentPaise)||currentPaise<0||!Number.isFinite(asOf)||contributions.some(c=>!Number.isFinite(c.amountPaise)||c.amountPaise<=0||!Number.isFinite(c.date)||c.date>asOf)||!contributions.some(c=>c.date<asOf))return null;
  if(currentPaise===0)return -1;
  const futureValue=logRate=>contributions.reduce((sum,c)=>sum+c.amountPaise*Math.exp(logRate*(asOf-c.date)/86400000/365),0)-currentPaise;
  let low=-32,high=32;
  if(futureValue(low)>0||futureValue(high)<0)return null;
  for(let i=0;i<120;i++){const mid=(low+high)/2;if(futureValue(mid)>0)high=mid;else low=mid}
  return Math.expm1((low+high)/2);
}
function rewardXirrLabel(value){return value===null?'—':(value>0?'+':'')+(value*100).toFixed(2)+'%'}
function rewardPortfolioStats(){const p=rewardPortfolio();return `<dl class="home-reward-portfolio"><div><dt>Invested amount</dt><dd>${rewardCurrency(p.investedPaise)}</dd></div><div><dt>Current value</dt><dd>${p.currentPaise===null?'—':rewardCurrency(p.currentPaise)}</dd></div><div><dt><button data-action="reward-performance" aria-label="Understand your reward portfolio and XIRR">XIRR ${icon('info',11)}</button></dt><dd class="${p.xirr===null?'':p.xirr<0?'return-negative':'return-positive'}">${rewardXirrLabel(p.xirr)}</dd></div></dl><p class="home-reward-nav-note">Demo NAV · 26 Oct 2026</p>`}
function rewardPerformanceDialog(){const p=rewardPortfolio();openDialog('Your rewards, invested.',`<div class="eyebrow">REWARD MUTUAL FUNDS · DEMO PORTFOLIO</div><h3>A clearer view of your growth.</h3><div class="receipt"><div class="data-row"><span>Invested amount</span><strong>${rewardCurrency(p.investedPaise)}</strong></div><div class="data-row"><span>Current value</span><strong>${p.currentPaise===null?'Unavailable':rewardCurrency(p.currentPaise)}</strong></div><div class="data-row"><span>Unrealised ${p.gainPaise<0?'loss':'gain'}</span><strong>${p.gainPaise===null?'Unavailable':rewardCurrency(p.gainPaise)}</strong></div><div class="data-row"><span>XIRR · annualised</span><strong>${rewardXirrLabel(p.xirr)}</strong></div><div class="data-row"><span>NAV as of</span><strong>26 Oct 2026 · demo</strong></div><div class="data-row"><span>Conversions awaiting allotment</span><strong>${rewardCurrency(rewardSummary().processingPaise)}</strong></div></div><p class="lead">Invested amount is the rupee value of rewards with units allotted. Current value is those units multiplied by each fund’s demo NAV.</p><p class="lead">XIRR is the annualised return calculated from each investment’s amount and allotment date, with the current portfolio value on the NAV date. It includes only allotted reward investments.</p><p class="amount-note">${p.xirr===null?'XIRR needs at least one investment dated before the NAV date; it is shown as a dash when it cannot be calculated. ':''}All values and returns are simulated. Available points, pending conversions and the portfolio backing your card are excluded.</p>`,`<button class="primary-button" data-action="close">Got it</button><button class="secondary-button" data-action="go-rewards">All rewards ${icon('arrow',15)}</button>`)}
function rewardCurrency(paise){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:paise%100?2:0,minimumFractionDigits:paise%100?2:0}).format(paise/100)}
function rewardPoints(points){return points.toLocaleString('en-IN')}
function selectedRewardFund(){return rewardFunds.find(f=>f.id===state.rewards.fundId)}
function canInvestRewards(points=state.rewards.availablePoints){return !!(state.rewards.ready&&state.rewards.consent&&selectedRewardFund()&&Number.isInteger(state.rewards.availablePoints)&&Number.isInteger(points)&&points>=REWARD_MIN_POINTS&&points<=state.rewards.availablePoints)}
function rewardStatus(order){return order.status==='allotted'?'Units allotted':order.status==='processing'?'Investment processing':'Conversion requested'}
function rewardPrimaryButton(home=false){
  const s=rewardSummary(),r=state.rewards;
  if(!r.ready)return `<button class="primary-button full" data-action="reward-setup">Set up reward investing ${icon('arrow',16)}</button>`;
  if(s.availablePoints>=REWARD_MIN_POINTS)return `<button class="primary-button full" data-action="invest-rewards">Invest ${rewardCurrency(s.availablePaise)} ${icon('arrowUp',16)}</button>`;
  if(home&&s.lastPending)return `<button class="primary-button full" data-action="reward-order" data-id="${s.lastPending.id}">Track investment ${icon('arrow',16)}</button>`;
  if(home)return `<button class="primary-button full" data-action="go-rewards">View investments ${icon('arrow',16)}</button>`;
  return '<button class="primary-button full" disabled>No rewards ready to invest</button>';
}
function rewardMonthlyConversions(range=rewardChartRange){
  const end=Date.parse(REWARD_NAV_DATE+'T00:00:00Z'),endDate=new Date(end),last=endDate.getUTCFullYear()*12+endDate.getUTCMonth();
  const orders=state.rewards.orders.map(order=>({order,date:rewardInvestmentDate({date:order.convertedOn||order.date})})).filter(({order:o,date})=>['requested','processing','allotted'].includes(o.status)&&Number.isInteger(o.points)&&o.points>0&&Number.isFinite(date)&&date<=end);
  const first=orders.length?Math.min(...orders.map(({date})=>{const d=new Date(date);return d.getUTCFullYear()*12+d.getUTCMonth()})):last;
  const count=range==='All'?last-first+1:range==='1Y'?12:range==='3M'?3:6;
  return Array.from({length:count},(_,i)=>{const month=last-count+1+i,date=new Date(Date.UTC(Math.floor(month/12),month%12,1)),key=date.toISOString().slice(0,7),items=orders.filter(({date:d})=>new Date(d).toISOString().slice(0,7)===key).map(v=>v.order);return{key,label:date.toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'}),fullLabel:date.toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}),points:items.reduce((sum,o)=>sum+o.points,0),pendingPoints:items.filter(o=>o.status!=='allotted').reduce((sum,o)=>sum+o.points,0),orders:items.length}});
}
function rewardChartMarkup(){
  const months=rewardMonthlyConversions(),maximum=Math.max(1,...months.map(m=>m.points)),selected=months.find(m=>m.key===rewardChartMonth)||months.at(-1),total=months.reduce((sum,m)=>sum+m.points,0),segments='<i></i>'.repeat(12);
  return `<div class="rp-chart-heading"><span>RP redeemed for mutual funds</span><span>${rewardPoints(total)} RP</span></div><div class="rp-month-bars ${months.length>6?'dense':''}" style="--month-count:${months.length}" role="group" aria-label="Monthly reward points converted to mutual funds">${months.map((m,i)=>`<button class="rp-month-bar ${selected.key===m.key?'selected':''} ${m.points?'has-points':''}" data-action="reward-chart-month" data-month="${m.key}" aria-pressed="${selected.key===m.key}" aria-label="${m.fullLabel}: ${rewardPoints(m.points)} RP redeemed${m.pendingPoints?', '+rewardPoints(m.pendingPoints)+' RP awaiting allotment':''}" title="${m.fullLabel}: ${rewardPoints(m.points)} RP"><span class="rp-pillar" aria-hidden="true"><span class="rp-pillar-track">${segments}</span><span class="rp-pillar-fill" style="clip-path:inset(${100-m.points/maximum*100}% 0 0)">${segments}</span></span><span class="rp-month-label ${months.length>6&&i%3!==0&&i!==months.length-1?'sparse-label':''}">${m.label}</span></button>`).join('')}</div><div class="rp-month-summary" aria-live="polite"><div><span>${selected.fullLabel}</span><strong>${rewardPoints(selected.points)} RP</strong></div><small>${selected.points?rewardCurrency(selected.points*REWARD_RATE_PAISE)+' converted'+(selected.pendingPoints?' · '+rewardPoints(selected.pendingPoints)+' RP awaiting allotment':' · Units allotted'):'No points converted this month'}</small></div><div class="rp-chart-ranges" role="group" aria-label="Reward conversion history period">${['3M','6M','1Y','All'].map(range=>`<button data-action="reward-chart-range" data-range="${range}" class="${rewardChartRange===range?'active':''}" aria-pressed="${rewardChartRange===range}">${range}</button>`).join('')}</div>`;
}
function setRewardChartRange(range){if(!['3M','6M','1Y','All'].includes(range))return false;rewardChartRange=range;rewardChartMonth=null;return true}
function selectRewardChartMonth(key){if(!rewardMonthlyConversions().some(m=>m.key===key))return false;rewardChartMonth=key;return true}
function rewardHomeHero(){
  const s=rewardSummary(),p=rewardPortfolio(),fund=selectedRewardFund(),pendingOnly=s.availablePoints<REWARD_MIN_POINTS&&s.lastPending;
  return `<section class="home-reward-hero rp-portfolio-hero" aria-label="Reward investment portfolio"><div class="spread"><span class="eyebrow">${icon('leaf',12)} YOUR REWARDS, INVESTED</span><span class="reward-demo-tag">Demo</span></div><p class="rp-value-label">Current value</p><div class="rp-current-value">${p.currentPaise===null?'—':`<span>₹</span>${rewardCurrency(p.currentPaise).slice(1)}`}</div><button class="rp-xirr ${p.xirr!==null&&p.xirr<0?'negative':''}" data-action="reward-performance" aria-label="Understand your reward portfolio and XIRR"><strong>${rewardXirrLabel(p.xirr)}</strong><span>XIRR · annualised</span>${icon('info',11)}</button><div class="rp-invested-line"><span>Invested amount <strong>${rewardCurrency(p.investedPaise)}</strong></span><span>NAV · 26 Oct ’26</span></div><div id="home-rp-chart" data-reward-chart>${rewardChartMarkup()}</div><div class="rp-invest-ready"><span>${pendingOnly?rewardStatus(s.lastPending):s.availablePoints===0?'No points ready to convert':rewardPoints(s.availablePoints)+' RP ready to convert'}</span><strong>${pendingOnly?rewardCurrency(s.lastPending.amountPaise):rewardCurrency(s.availablePaise)}</strong></div>${fund&&!pendingOnly&&s.availablePoints>=REWARD_MIN_POINTS?`<div class="home-reward-destination"><span>${icon('leaf',13)}${esc(fund.name)}</span><small>Fee ₹0 · demo</small></div>`:''}${rewardPrimaryButton(true)}<div class="home-reward-footer"><span>${fund?'10 points = ₹1 · demo':'Choose once. Invest in a click.'}</span><button class="text-button" data-action="go-rewards">All rewards ${icon('arrow',13)}</button></div></section>`;
}
function changeRewardChart(el,type){const chart=el.closest('[data-reward-chart]');if(!chart)return;const valid=type==='range'?setRewardChartRange(el.dataset.range):selectRewardChartMonth(el.dataset.month);if(!valid)return;chart.innerHTML=rewardChartMarkup();chart.querySelector(type==='range'?'[data-range="'+rewardChartRange+'"]':'[data-month="'+rewardChartMonth+'"]')?.focus({preventScroll:true})}
function rewardOrderRow(order){const fund=rewardFunds.find(f=>f.id===order.fundId);return `<button class="reward-order-row" data-action="reward-order" data-id="${order.id}"><span class="reward-order-icon">${icon(order.status==='allotted'?'leaf':'arrowUp',19)}</span><span class="reward-order-name"><strong>${fund.name}</strong><small>${order.date} · ${rewardPoints(order.points)} points</small></span><span class="reward-order-right"><strong>${rewardCurrency(order.amountPaise)}</strong><span class="reward-status ${order.status==='allotted'?'allotted':''}">${rewardStatus(order)}</span></span>${icon('chevron',15)}</button>`}
function rewardOrdersMarkup(){const orders=state.rewards.orders.filter(o=>rewardFilter==='All'||rewardFilter==='Processing'&&o.status!=='allotted'||rewardFilter==='Allotted'&&o.status==='allotted');return orders.length?orders.map(rewardOrderRow).join(''):`<div class="reward-empty">${icon('leaf',27)}<h3>${rewardFilter==='Processing'?'Nothing processing right now.':'Your next chapter starts here.'}</h3><p>Conversions appear here with their latest investment status.</p></div>`}
function rewardsPage(){return rewardHubPage()}
function rewardSetupDialog(){
  const current=state.rewards.fundId;
  openDialog(current?'Your investment destination':'Set up reward investing',`<div class="eyebrow">A ONE-TIME CHOICE</div><h3>Give your rewards a destination.</h3><p class="lead">Choose a demo investment. Once set up, the amount and destination are shown before every single-click conversion.</p><div class="reward-setup-status">${icon('shield',17)}<span>Investor profile: <strong>demo verified</strong></span></div><fieldset class="reward-fund-options"><legend>Choose a demo fund</legend>${rewardFunds.map(f=>`<label class="reward-fund-option"><input type="radio" name="reward-fund" value="${f.id}" ${current===f.id?'checked':''}><span><span class="spread"><strong>${f.name}</strong><small class="soft-badge">Demo fund</small></span><small>${f.type} · ${f.risk}</small><span class="reward-fund-description">${f.description}</span></span></label>`).join('')}</fieldset><div class="callout">${icon('info',17)}These funds are fictional and not investment recommendations. In this prototype, 10 points convert to ₹1 with a ₹0 conversion fee.</div><label class="check-label"><input type="checkbox" id="reward-setup-consent"><span>I authorise this demo destination for future reward conversions and understand that the funds, balances, and orders are simulated. Investing can involve loss; no returns are promised.</span></label><p class="field-help">Only available reward points are converted. No bank account is charged, and pending points stay excluded.</p>`,`<button class="primary-button" id="save-reward-setup" data-action="save-reward-setup" disabled>Save investment destination ${icon('arrow',16)}</button><span class="small">Setup does not convert any points.</span>`);
}
function updateRewardSetup(){const button=$('#save-reward-setup');if(button)button.disabled=!($('input[name="reward-fund"]:checked')&&$('#reward-setup-consent')?.checked)}
function setRewardDestination(fundId,consent){if(!rewardFunds.some(f=>f.id===fundId)||consent!==true)return false;state.rewards.fundId=fundId;state.rewards.ready=true;state.rewards.consent=true;save();return true}
function saveRewardSetup(){const fundId=$('input[name="reward-fund"]:checked')?.value;if(!setRewardDestination(fundId,$('#reward-setup-consent')?.checked))return;render();openDialog('Ready for your next move.',`<div class="success"><div class="success-icon">${icon('leaf',29)}</div><h3>Choose once.<br>Invest in a click.</h3><p>When you choose mutual fund investing, your demo points will go to <strong>${selectedRewardFund().name}</strong> when you choose to convert them.</p></div><div class="receipt"><div class="data-row"><span>Available for mutual funds</span><strong>${rewardCurrency(rewardSummary().availablePaise)}</strong></div><div class="data-row"><span>Points still available</span><strong>${rewardPoints(state.rewards.availablePoints)}</strong></div><div class="data-row"><span>Conversion fee · demo</span><strong>₹0</strong></div></div><p class="amount-note">No points have moved. Your next investment takes a single click from Home or Rewards.</p>`,`<button class="primary-button" data-action="finish-rewards">Go to my rewards ${icon('arrow',16)}</button>`)}
function createRewardInvestment(points=state.rewards.availablePoints){
  if(!canInvestRewards(points))return null;
  const r=state.rewards;
  const order={id:'ELV-RW-'+String(r.orders.length+1).padStart(4,'0'),points,amountPaise:points*REWARD_RATE_PAISE,fundId:r.fundId,status:'requested',units:null,navPaise:null,date:'26 Oct 2026 · Just now',source:'Single-click demo conversion',createdAt:Date.now()};
  r.availablePoints-=points;
  r.orders.unshift(order);
  save();return order;
}
function investRewards(el){if(!state.rewards.ready){rewardSetupDialog();return}const order=createRewardInvestment(el?.dataset?.points===undefined?undefined:Number(el.dataset.points));if(!order){toast('No available points are ready to convert. Pending points stay separate.');return}render();rewardOrderDialog(order.id,true)}
function advanceRewardInvestment(id){const order=state.rewards.orders.find(o=>o.id===id);if(!order||order.status==='allotted')return false;if(order.status==='requested')order.status='processing';else if(order.status==='processing'){order.status='allotted';order.allottedOn=REWARD_NAV_DATE;order.navPaise=rewardFunds.find(f=>f.id===order.fundId).navPaise;order.units=Number((order.amountPaise/order.navPaise).toFixed(4))}else return false;save();return true}
function rewardOrderDialog(id,fresh=false){
  const order=state.rewards.orders.find(o=>o.id===id);if(!order)return;
  const fund=rewardFunds.find(f=>f.id===order.fundId),allotted=order.status==='allotted',processing=order.status==='processing';
  openDialog(fresh?'Your rewards are on their way.':'Reward investment details',`
    ${fresh?`<div class="reward-receipt-intro"><div class="success-icon">${icon('check',28)}</div><h3>One click.<br>A new possibility.</h3><p>${rewardPoints(order.points)} points converted into a demo investment request.</p></div>`:`<div class="eyebrow">${order.id} · DEMO INVESTMENT</div><h3>${rewardStatus(order)}</h3>`}
    <div class="reward-receipt-amount">${rewardCurrency(order.amountPaise)}</div><p class="lead">${fund.name} <span class="soft-badge">Demo fund</span></p>
    <ol class="reward-timeline"><li class="done"><span>${icon('check',13)}</span><div><strong>Points converted</strong><small>${rewardPoints(order.points)} points deducted · ${rewardCurrency(order.amountPaise)} requested</small></div></li><li class="${processing||allotted?'done':'waiting'}"><span>${icon(processing||allotted?'check':'activity',13)}</span><div><strong>${processing||allotted?'Investment processing':'Awaiting investment processing'}</strong><small>${allotted?'Demo order processed':processing?'Your demo order is being processed.':'Your conversion request has been received.'}</small></div></li><li class="${allotted?'done':'waiting'}"><span>${icon(allotted?'check':'leaf',13)}</span><div><strong>${allotted?'Units allotted':'Units awaiting allotment'}</strong><small>${allotted?order.units.toFixed(4)+' demo units at '+rewardCurrency(order.navPaise)+' per unit':'An investment is only shown as allotted after confirmation.'}</small></div></li></ol>
    <div class="receipt"><div class="data-row"><span>Reference</span><strong>${order.id}</strong></div><div class="data-row"><span>Status</span><strong>${rewardStatus(order)}</strong></div><div class="data-row"><span>Conversion rate</span><strong>10 points = ₹1 · demo</strong></div><div class="data-row"><span>Conversion fee</span><strong>₹0 · demo</strong></div><div class="data-row"><span>Investment units</span><strong>${allotted?order.units.toFixed(4):'Pending allotment'}</strong></div></div>
    <p class="amount-note">No real investment or bank debit. ${allotted?'These are simulated units.':'Processing and unit allotment have not been represented as completed.'} Reward investments stay unpledged and do not change your card limit.</p>
    ${!allotted?`<details class="reward-demo-controls"><summary>Demo: preview the next status</summary><p>Advance this fictional order to explore the complete journey.</p><button class="secondary-button full" data-action="advance-reward" data-id="${order.id}">${processing?'Simulate unit allotment':'Simulate investment processing'} ${icon('arrow',15)}</button></details>`:''}`,
    `<button class="primary-button" data-action="finish-rewards">View my rewards ${icon('arrow',16)}</button><button class="secondary-button" data-action="close">Done</button>`);
}
function rewardPointsDialog(){const s=rewardSummary();openDialog('Your points, clearly.',`<div class="eyebrow">REWARD POINTS BALANCE</div><h3>Know what’s ready.</h3><div class="panel"><div class="data-row"><span>Available to redeem</span><strong>${rewardPoints(s.availablePoints)} points</strong></div><div class="data-row"><span>Mutual fund conversion value</span><strong>${rewardCurrency(s.availablePaise)}</strong></div><div class="data-row"><span>Pending · not convertible</span><strong>${rewardPoints(s.pendingPoints)} points</strong></div><div class="data-row"><span>Points converted to mutual funds</span><strong>${rewardPoints(s.convertedPoints)} points</strong></div><div class="data-row"><span>Points used for other rewards</span><strong>${rewardPoints(state.rewards.redemptions.reduce((n,r)=>n+r.points,0))} points</strong></div></div><p class="lead">Pending points are kept outside the single-click conversion balance. They are not deducted or invested by the demo conversion.</p><div class="callout">${icon('info',17)}Sample terms: 10 points = ₹1, a minimum of 100 points, and a ₹0 conversion fee. Earning rates and availability rules are placeholders, not live card terms.</div>`,`<button class="primary-button" data-action="close">Got it</button>`)}
function rewardHowDialog(){openDialog('From rewards to investments.',`<div class="eyebrow">A SMALL HABIT. A DIFFERENT FUTURE.</div><h3>Choose once.<br>Invest in a click.</h3><div class="reward-how-step"><span>01</span><div><h4>Pick your investment</h4><p>Complete the one-time demo setup and save a destination. No points move during setup.</p></div></div><div class="reward-how-step"><span>02</span><div><h4>Know what you’re converting</h4><p>Your available points, rupee value, fund, and demo fee are shown before the Invest button. One click submits the request.</p></div></div><div class="reward-how-step"><span>03</span><div><h4>Follow the investment</h4><p>See conversion requested, investment processing, and units allotted as distinct steps. No investment returns are assumed.</p></div></div><div class="callout">${icon('shield',17)}Reward investments are separate from the pledged portfolio backing your card. No automatic pledge or increase in your limit takes place.</div><p class="amount-note">All funds and terms in this prototype are fictional. This flow places no actual investment and charges no bank account.</p>`,`<button class="primary-button" data-action="finish-rewards">Explore my rewards ${icon('arrow',16)}</button>`)}
